// Hand-written. Not generated by Speakeasy.
//
// Authlete stores a JWK Set as an opaque JSON string and returns it in a
// normalised form: whitespace stripped and member keys reordered. A byte
// comparison therefore reports a change on every plan after the first apply,
// even though nothing changed. Measured against the live API, one such
// difference cascaded into 214 attributes showing as "known after apply".
//
// This type compares two JWK Sets by parsing them instead, so semantically
// equal documents compare equal regardless of formatting.
package customtypes

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/diag"
	"github.com/hashicorp/terraform-plugin-framework/types/basetypes"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// --- type -------------------------------------------------------------------

var (
	_ basetypes.StringTypable = (*JWKSType)(nil)
)

// JWKSType is a string type whose values compare by JSON meaning.
type JWKSType struct {
	basetypes.StringType
}

func (t JWKSType) Equal(o attr.Type) bool {
	other, ok := o.(JWKSType)
	if !ok {
		return false
	}
	return t.StringType.Equal(other.StringType)
}

func (t JWKSType) String() string { return "customtypes.JWKSType" }

func (t JWKSType) ValueFromString(_ context.Context, in basetypes.StringValue) (basetypes.StringValuable, diag.Diagnostics) {
	return JWKS{StringValue: in}, nil
}

func (t JWKSType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	attrValue, err := t.StringType.ValueFromTerraform(ctx, in)
	if err != nil {
		return nil, err
	}

	stringValue, ok := attrValue.(basetypes.StringValue)
	if !ok {
		return nil, fmt.Errorf("unexpected value type %T, expected basetypes.StringValue", attrValue)
	}

	stringValuable, diags := t.ValueFromString(ctx, stringValue)
	if diags.HasError() {
		return nil, fmt.Errorf("unexpected error converting StringValue to StringValuable: %v", diags)
	}

	return stringValuable, nil
}

func (t JWKSType) ValueType(_ context.Context) attr.Value { return JWKS{} }

// --- value ------------------------------------------------------------------

var (
	_ basetypes.StringValuableWithSemanticEquals = (*JWKS)(nil)
)

// JWKS is a JWK Set document held as a string.
type JWKS struct {
	basetypes.StringValue
}

func (v JWKS) Equal(o attr.Value) bool {
	other, ok := o.(JWKS)
	if !ok {
		return false
	}
	return v.StringValue.Equal(other.StringValue)
}

func (v JWKS) Type(_ context.Context) attr.Type { return JWKSType{} }

// StringSemanticEquals reports whether two JWK Sets mean the same thing.
//
// Anything that does not parse as JSON falls back to exact comparison, so a
// malformed document still produces a visible diff rather than being silently
// treated as equal to whatever is stored.
func (v JWKS) StringSemanticEquals(_ context.Context, newValuable basetypes.StringValuable) (bool, diag.Diagnostics) {
	var diags diag.Diagnostics

	newValue, ok := newValuable.(JWKS)
	if !ok {
		diags.AddError(
			"Semantic Equality Check Error",
			fmt.Sprintf("expected value type %T but got %T. Please report this to the provider developers.", v, newValuable),
		)
		return false, diags
	}

	oldRaw, newRaw := v.ValueString(), newValue.ValueString()
	if oldRaw == newRaw {
		return true, diags
	}

	var oldDoc, newDoc any
	if err := json.Unmarshal([]byte(oldRaw), &oldDoc); err != nil {
		return false, diags
	}
	if err := json.Unmarshal([]byte(newRaw), &newDoc); err != nil {
		return false, diags
	}

	return reflect.DeepEqual(oldDoc, newDoc), diags
}

// NewJWKSValue and friends mirror the constructors the framework expects.
func NewJWKSValue(value string) JWKS {
	return JWKS{StringValue: basetypes.NewStringValue(value)}
}

func NewJWKSNull() JWKS {
	return JWKS{StringValue: basetypes.NewStringNull()}
}

func NewJWKSUnknown() JWKS {
	return JWKS{StringValue: basetypes.NewStringUnknown()}
}
